        Clock clock = mock(Clock.class);
        FundTransferService fundTransferService = new FundTransferService(accountRepository, clock);

        Account fromAccount = new Account("12345", "John Doe", new BigDecimal("1000"));
        Account toAccount = new Account("67890", "Jane Smith", new BigDecimal("500"));
