require_relative 'spec/pages/fund_transfer_page'

describe 'Fund Transfer' do
  let(:driver) { Selenium::WebDriver.for :chrome }

  before do
    @page = FundTransferPage.new(driver)
    @page.navigate_to
  end

  after do
    driver.quit
  end

  it 'should transfer funds between accounts successfully' do
    @page.select_source_account
    @page.select_destination_account
    @page.enter_amount
    @page.submit_transfer
    expect(@page.verify_transfer_success).to be true
  end

  it 'should not transfer funds between accounts if the receiving account does not have enough funds' do
    @page.select_source_account
    @page.select_destination_account
    @page.enter_amount
    @page.submit_transfer
    expect(@page.verify_transfer_failure).to be true
  end

  it 'should log the transfer details in the audit trail' do
    @page.select_source_account
    @page.select_destination_account
    @page.enter_amount
    @page.submit_transfer
    expect(@page.verify_audit_log).to be true
  end
end

